export class FreeCamera extends Camera {
    public position: Vector3;
    public target: Vector3;
    public _yaw: number;
    public _pitch: number;
    public angularSensitivity: number;
    public inertia: number;

    constructor(name: string, position: Vector3, scene: Scene, noInertia?: boolean) {
        super(name, position, scene);
        this.target = new Vector3(0, 0, 0);
        this._yaw = 0;
        this._pitch = 0;
        this.angularSensitivity = 0.01;
        this.inertia = noInertia ? 0 : 0.9;
    }

    public getViewMatrix(): Matrix {
        const view = this._viewCache;
        const sinPitch = Math.sin(this._pitch);
        const cosPitch = Math.cos(this._pitch);
        const sinYaw = Math.sin(this._yaw);
        const cosYaw = Math.cos(this._yaw);
        view[0] = cosYaw;
        view[1] = -sinYaw * sinPitch;
        view[2] = sinYaw * cosPitch;
        view[4] = sinYaw;
        view[5] = cosYaw * sinPitch;
        view[6] = -cosYaw * cosPitch;
        view[8] = -sinPitch;
        view[9] = cosPitch;
        view[10] = 0;
        view[12] = -this.position.x;
        view[13] = -this.position.y;
        view[14] = -this.position.z;
        return view;
    }

    public setTarget(target: Vector3): FreeCamera {
        const dx = target.x - this.position.x;
        const dy = target.y - this.position.y;
        const dz = target.z - this.position.z;
        this._yaw = Math.atan2(dx, dz);
        this._pitch = Math.atan2(dy, Math.sqrt(dx * dx + dz * dz));
        return this;
    }
}
